-- =====================================================================
-- StockSense — real SOXX history for the Trading Game (pages/game.php)
--
-- The game replays a random ~1-year window of REAL SOXX (iShares
-- Semiconductor ETF) daily prices, and shows the real headlines from
-- news_articles on the days they were published.
--
-- Prices are split-adjusted (SOXX split 3-for-1 in March 2024), from
-- Yahoo Finance daily data, 2022-01-03 to 2026-10-27.
-- To add newer days later, run:  php api/fetch_game_prices.php
--
-- Run once, AFTER sql/schema.sql and 002_trading_game.sql. Safe to re-run.
--   phpMyAdmin: select the stocksense database -> Import -> this file (utf8mb4)
-- =====================================================================

USE stocksense;

CREATE TABLE IF NOT EXISTS game_soxx_daily (
    trade_date  DATE PRIMARY KEY,
    open_price  DECIMAL(10,2) NOT NULL,
    high_price  DECIMAL(10,2) NOT NULL,
    low_price   DECIMAL(10,2) NOT NULL,
    close_price DECIMAL(10,2) NOT NULL
) ENGINE=InnoDB;

ON DUPLICATE KEY UPDATE
    open_price = VALUES(open_price), high_price = VALUES(high_price),
    low_price = VALUES(low_price), close_price = VALUES(close_price);
